"use client";

import { useEffect, useState } from "react";
import { fmt, parseStats, pct, type Stats, utcShort } from "@/lib/stats";
import { HourlyChart } from "./hourly-chart";
import { RankedList } from "./ranked-list";
import { WorldMap } from "./world-map";

const DATASET_NOTE: Record<string, string> = {
  sample:
    "Sample data. Generated by tools/generate_sample_logs.py to exercise the pipeline; these are not observed attacks.",
  "local-test":
    "Local test data. Scripted logins against Cowrie on a development machine; not internet traffic.",
};

type State = { kind: "loading" } | { kind: "error"; message: string } | { kind: "ok"; stats: Stats };

export function HoneypotDashboard({ src }: { src: string }) {
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    const ctrl = new AbortController();
    fetch(src, { signal: ctrl.signal, cache: "no-store", credentials: "omit" })
      .then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        return r.json();
      })
      .then((raw) => setState({ kind: "ok", stats: parseStats(raw) }))
      .catch((e: unknown) => {
        if (!ctrl.signal.aborted) {
          setState({ kind: "error", message: e instanceof Error ? e.message : String(e) });
        }
      });
    return () => ctrl.abort();
  }, [src]);

  if (state.kind === "loading") {
    return <p className="hp-note" style={{ padding: "48px 0" }}>Loading stats…</p>;
  }
  if (state.kind === "error") {
    return (
      <p className="hp-banner" role="alert">
        Stats unavailable ({state.message}). The sensor publishes every ten minutes; try again shortly.
      </p>
    );
  }
  return <Loaded s={state.stats} />;
}

function Loaded({ s }: { s: Stats }) {
  const t = s.totals;
  const note = DATASET_NOTE[s.dataset];
  const live = s.dataset === "live";

  return (
    <>
      <div className="hp-meta">
        <span>
          {live && <span className="hp-pulse" aria-hidden="true" />}
          window <b>{s.window.days} days</b> to <b>{utcShort(s.window.end)} UTC</b>
        </span>
        <span>
          updated <b>{utcShort(s.generated_at)} UTC</b>
        </span>
        <span>
          dataset <b>{s.dataset}</b>
        </span>
      </div>
      {note && <p className="hp-banner">{note}</p>}

      <section className="sh-sec" aria-label="Totals">
        <div className="hp-kpis">
          <Kpi label="sessions" value={fmt(t.sessions)}
            sub={`${pct(t.ssh_sessions, t.sessions)} SSH · ${pct(t.telnet_sessions, t.sessions)} Telnet`} />
          <Kpi label="login attempts" value={fmt(t.login_attempts)}
            sub={`${fmt(t.login_successes)} let into the fake shell`} />
          <Kpi label="source addresses" value={fmt(t.unique_sources)}
            sub={`${fmt(t.countries)} countries · ${fmt(t.asns)} networks`} />
          <Kpi label="commands run" value={fmt(t.commands)} sub={`${fmt(t.unique_commands)} distinct`} />
          <Kpi label="payloads" value={fmt(t.payloads)}
            sub={`${fmt(t.downloads_blocked)} downloads blocked`} />
        </div>
      </section>

      <section className="sh-sec">
        <div className="sh-split">
          <div className="sh-label">
            <h2 className="sh-h2">Sessions per hour</h2>
            <p className="hp-note">Last 7 days, UTC. Hover a column for the hour.</p>
          </div>
          <div className="sh-body">
            <HourlyChart hours={s.hourly} />
          </div>
        </div>
      </section>

      <section className="sh-sec">
        <div className="sh-split">
          <div className="sh-label">
            <h2 className="sh-h2">Where it comes from</h2>
            <p className="hp-note">
              Source country and network of each session, looked up offline. Addresses are counted,
              never published.
            </p>
          </div>
          <div className="sh-body">
            <WorldMap data={s.countries} total={t.sessions} />
            <div className="hp-grid" style={{ marginTop: 32 }}>
              <RankedList title="Top countries" unit="sessions"
                rows={s.countries.map((c) => ({ key: c.code, label: c.name, note: c.code, value: c.sessions }))} />
              <RankedList title="Top networks (ASN)" unit="sessions"
                rows={s.asns.map((a) => ({ key: String(a.asn), label: a.org || `AS${a.asn}`, note: `AS${a.asn}`, value: a.sessions }))} />
            </div>
          </div>
        </div>
      </section>

      <section className="sh-sec">
        <div className="sh-split">
          <div className="sh-label">
            <h2 className="sh-h2">What they try</h2>
            <p className="hp-note">
              Credentials guessed at the login prompt. These are the dictionaries bots ship with.
            </p>
          </div>
          <div className="sh-body hp-grid">
            <RankedList title="Usernames" unit="attempts"
              rows={s.usernames.map((u) => ({ key: u.value, label: u.value, value: u.count }))} />
            <RankedList title="Passwords" unit="attempts"
              rows={s.passwords.map((p) => ({ key: p.value, label: p.value, value: p.count }))} />
            <RankedList title="Pairs" unit="attempts"
              rows={s.credentials.map((c) => ({ key: `${c.username}\u0000${c.password}`, label: `${c.username} / ${c.password}`, value: c.count }))} />
            <RankedList title="SSH clients" unit="sessions"
              rows={s.client_versions.map((c) => ({ key: c.value, label: c.value, value: c.count }))} />
          </div>
        </div>
      </section>

      <section className="sh-sec">
        <div className="sh-split">
          <div className="sh-label">
            <h2 className="sh-h2">What they run</h2>
            <p className="hp-note">
              Typed into an emulated shell; nothing executes. Addresses are cut to /24 and links are
              defanged (hxxp, [.]) before publishing.
            </p>
          </div>
          <div className="sh-body">
            <RankedList title="Most common commands" unit="times" limit={12}
              rows={s.commands.map((c) => ({ key: c.value, label: c.value, value: c.count }))} />
            <h3 className="sh-h2" style={{ fontSize: 18, margin: "40px 0 10px" }}>Recent, newest first</h3>
            {s.recent_commands.length === 0 ? (
              <p className="hp-empty">No commands in this window.</p>
            ) : (
              <table className="hp-table">
                <thead>
                  <tr>
                    <th scope="col">UTC</th>
                    <th scope="col" className="cc-col">from</th>
                    <th scope="col">command</th>
                  </tr>
                </thead>
                <tbody>
                  {s.recent_commands.map((c) => (
                    <tr key={c.cmd + c.t}>
                      <td className="when">{utcShort(c.t)}</td>
                      <td className="cc">{c.country === "ZZ" ? "—" : c.country}</td>
                      <td className="cmd"><code>{c.cmd}</code></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </section>

      <section className="sh-sec">
        <div className="sh-split">
          <div className="sh-label">
            <h2 className="sh-h2">Payloads</h2>
            <p className="hp-note">
              Files pushed in over SFTP/SCP, by SHA-256. The files stay on the sensor; outbound
              downloads are blocked at the host firewall, so droppers fail and are only counted.
            </p>
          </div>
          <div className="sh-body">
            {s.payloads.length === 0 ? (
              <p className="hp-empty">No payloads captured in this window.</p>
            ) : (
              <table className="hp-table">
                <thead>
                  <tr>
                    <th scope="col">sha256</th>
                    <th scope="col">seen</th>
                    <th scope="col">first</th>
                  </tr>
                </thead>
                <tbody>
                  {s.payloads.map((p) => (
                    <tr key={p.sha256}>
                      <td className="hp-hash">
                        {live ? (
                          <a className="sh-link" href={`https://www.virustotal.com/gui/file/${p.sha256}`}
                            target="_blank" rel="noopener noreferrer">{p.sha256}</a>
                        ) : (
                          p.sha256
                        )}
                      </td>
                      <td className="when">{fmt(p.count)}×</td>
                      <td className="when">{p.first_seen ? utcShort(p.first_seen) : ""}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </section>

      <footer className="hp-foot">
        <span>{s.attribution.geoip ?? "No GeoIP database loaded."}</span>
        <span>Aggregated and anonymised on the sensor. No full IPs, no malware, no session IDs.</span>
      </footer>
    </>
  );
}

function Kpi({ label, value, sub }: { label: string; value: string; sub: string }) {
  return (
    <div className="hp-kpi">
      <div className="label">{label}</div>
      <div className="sh-stat">{value}</div>
      <div className="sub">{sub}</div>
    </div>
  );
}
